lookup-when.specification:
schema_version: '1.0'
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: {path: src.csv}
  DONOR: {path: donor.csv, types: {SEQ: int, X: int}}
output: {path: result.csv, columns: [ID, VALUE]}
intermediates:
  - id: P
    dataset: DONOR
    key: [ID]
    order_by: [DONOR.SEQ]
    keep: first
    no_match: null
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: int, derivation: {literal: 2}}
verifications:
  - unique: {columns: [ID], id: prefix}
  - assert: {id: selected, when: "P.X = 2", require: "VALUE = 2"}
  - row_count: {min: 3, max: 3}

